"""All quantifier equivalence, prenex and natural deduction questions in DM5."""
import manual_solutions as author
def put(n,steps,errors):
 author.add('DM2T',f'005-{n:03}',steps,errors,'逐小问核对量词外提条件、避免捕获换名、非空域、临时见证与假设解除。')
def example(n,steps,errors):
 author.add_example('DM2T',n,steps,errors,'展开各量词或构造完整自然推理，核对自由变项与存在见证不泄漏。')

put(1,[r'设B=∃yG(y)，其中没有自由x。对非空域可用辖域收缩等值式∀x(F(x)∧B)≡(∀xF(x))∧B，乙的关键是先作这一等值变形，把与x无关的重复条件提到外面。',r'D={a,b,c}时，∀xF(x)展开为F(a)∧F(b)∧F(c)，B展开为Q=G(a)∨G(b)∨G(c)，最终(F(a)∧F(b)∧F(c))∧Q。Q已是无量词缩写。',r'甲的结果为(F(a)∧Q)∧(F(b)∧Q)∧(F(c)∧Q)，结合交换后等于F(a)∧F(b)∧F(c)∧Q∧Q∧Q，再用幂等律Q∧Q=Q，得到乙式。所以乙较简洁，甲并没有算错。'],[r'移出条件前须确认B没有自由x。',r'同一个存在条件在各支重复出现可幂等合并，但不同F(a)、F(b)不可合并。'])
put(2,[r'第（1）先展开∀x∃y(F(x)∧G(y))，每个x分支是F(x)∧(G(a)∨G(b)∨G(c))。三个分支合取，重复的G析取由幂等律合并，得到(F(a)∧F(b)∧F(c))∧(G(a)∨G(b)∨G(c))。',r'第（2）直接展开是九个F(u)∨G(v)的合取，u,v各取a,b,c。先对固定u把三项分配，得F(u)∨(G(a)∧G(b)∧G(c))；再对三个u分配，得(F(a)∧F(b)∧F(c))∨(G(a)∧G(b)∧G(c))。',r'第（3）两个全称分别展开，保持外蕴涵： (F(a)∧F(b)∧F(c))→(G(a)∧G(b)∧G(c))。不要误把它改成三个逐点蕴涵的合取。',r'第（4）先将内层约束y改名z，写∀x(F(x,y)→∃zG(z))，保留F中自由y。令已展开Q=G(a)∨G(b)∨G(c)，再展开外∀x，得(F(a,y)→Q)∧(F(b,y)→Q)∧(F(c,y)→Q)。结果仍有自由y，但已无量词，这符合题意。'],[r'消去量词不等于消去所有自由变项。',r'第（2）的简式用两次分配律，不能把∀任意分配到一个同变项析取上。'])
put(3,[r'域固定{1,2}，要同一个I₁同时使两式真。取F={1}、G={1}，即两者在1处真、2处假。逐点F→G为1→1与0→0，均真，全称真；存在合取在1处为1，真。',r'取I₂为F={1}、G={2}。在1处F真G假，F→G假，故全称假；在1处合取1∧0=0，在2处0∧1=0，没有合取见证，存在式假。',r'两个解释都完整规定域内每个谓词值，并分别满足“同真”“同假”的同时要求。只让某一个公式变假还不足以完成I₂。'],[r'两问需要在同一个解释中同时满足要求，不要分别挑两个不兼容的解释。',r'存在式为假须核查域中所有候选。'])
put(4,[r'第（1）D={a}时，∃xF(x)和∀xF(x)都只检查F(a)，所以A≡F(a)→F(a)。无论F(a)取0还是1，自蕴涵恒真。',r'第（2）n≥2可取F(a₁)=1、F(a₂)=0，其余值任意。存在式由a₁为真，全称式被a₂否定，故A=1→0=0，不再一定真。',r'若F处处真，A=1→1；若处处假，A=0→0，均真。所以n≥2时公式有真有假，不能因找到反例而称为矛盾式。'],[r'单元素域下的巧合不能推广至所有非空域。',r'反例要至少一个真点且一个假点，才能使存在真、全称假。'])
put(5,[r'把二元F列成行x、列y的表：行3为(0,1)，行4为(1,0)，f交换3和4。全称是各行合取，存在是各列或各候选析取，按量词嵌套次序计算。',r'第（1）∀x∃yF(x,y)：x=3选y=4，x=4选y=3，每行都至少一真，所以真。第（2）∃x∀yF(x,y)：两行各有一个0，没有全真行，所以假。',r'第（3）四对逐一核对： (3,3)前件0、(4,4)前件0，蕴涵均真；(3,4)前件1，后件F(4,3)=1；(4,3)前件1，后件F(3,4)=1。四项蕴涵全真，全称式真。'],[r'∀x∃y只要求每行有一个真，∃x∀y要求存在全真行。',r'f同时作用两个参数，不能只交换其中一个。'])
put(6,[r'要收缩∀x(A(x)→B)为(∃xA(x))→B，必须B无自由x。题中G(x,y)有x，移出后原先受约束的出现变自由，规则前提不满足，所以乙正确。',r'给完整反模型：D={0,1}，F全真；对两个y均规定G(0,y)=1,G(1,y)=0，右侧自由x赋0、y任意。',r'左侧∀u(F(u)→G(u,y))在u=1时1→0，假；右侧(∃uF(u))→G(0,y)为1→1，真。相同解释、赋值给不同真值，直接证明不等值。'],[r'辖域收缩不是随意挪动括号，移出部分不得依赖被量化变元。',r'比较含自由变量的公式时，反模型必须同时指定自由赋值。'])
put(7,[r'第一次错误是只交换∃、∀却丢掉矩阵否定。逐次用¬∃xA≡∀x¬A、¬∀yB≡∃y¬B，正确先得到∀x∃y¬(F(x)∧(G(y)→H(x,y)))。',r'继续对矩阵用德摩根与蕴涵否定：¬(F∧(G→H))≡¬F∨¬(¬G∨H)≡¬F∨(G∧¬H)。正确式为∀x∃y(¬F(x)∨(G(y)∧¬H(x,y)))。',r'第二次错误是F∧(G→H)不等值于(F∧G)→H。取F=0即可：左合取必0，右蕴涵前件0而为1。括号由合取变成蕴涵前件不是合法等值律；本题不能用它修复第一步。'],[r'量词否定会把量词反转，但否定号必须继续向矩阵内部传播。',r'A∧(B→C)与(A∧B)→C一般不同。'])
put(8,[r'第（1）域R，P正数、N负数、L小于。先否定存在反例：¬∃x∃y(P(x)∧N(y)∧L(x,y))。两次量词否定再对合取用德摩根，得∀x∀y(¬P(x)∨¬N(y)∨¬L(x,y))，改写为∀x∀y((P(x)∧N(y))→¬L(x,y))。',r'第（2）域为角，E为相等、V为互为对顶。“未必都”否定全称：¬∀x∀y(E(x,y)→V(x,y))。推否定进入，变成∃x∃y(E(x,y)∧¬V(x,y))。',r'第一问是没有任何坏例，第二问是至少一个反例。两组各自通过量词否定和德摩根律得到两种等值形式，而不是交换字面顺序。'],[r'角相等不必互为对顶，存在反例不意味着所有相等角都非对顶。',r'“不存在P且N且L”否定的是整个合取，不只否定P。'])
put(9,[r'左式∃xF(x)∧∃xG(x)的两量词辖域互不相同，可以先改名成∃uF(u)∧∃vG(v)，u、v可取不同个体。',r'本题F见证0是有理数，G见证√2是无理数，所以两个存在式及其合取都真；但F(x)∧G(x)要求同一个实数兼为有理、无理，二类互斥，右存在式假。',r'合法合并为∃u∃v(F(u)∧G(v))，而不是∃x(F(x)∧G(x))。后者推出前者，但前者不能一般推出后者；存在量词不对合取作这种分配。'],[r'两个存在事实可以靠不同见证成立，不要合并成一个人或一个数。',r'换约束变元名不改变语义，把两个独立见证强行等同才改变语义。'])
put(10,[r'前束范式的语法结构是Q₁x₁⋯Q_nx_n B，其中B无量词，全部量词必须位于最外前缀。原式最外符号为否定，量词在¬之后，故当前写法不是前束范式。',r'用量词否定¬∃xA≡∀x¬A，得到∀x¬(F(x)∧G(x))，这已是前缀∀x加无量词矩阵。',r'再用德摩根可写∀x(¬F(x)∨¬G(x))。后两个都是前束范式，矩阵中允许联结词和否定，不必只有单个原子式。'],[r'一个公式等值于前束式，不表示原写法本身已是前束式。',r'矩阵允许否定，禁止的是矩阵内还有量词。'])
put(11,[r'两个量词同名不妨碍换名，只对各自约束出现改名： (∀u(F(u)→G(u)))→∃vG(v,y)。自由y不改，u、v选为全新字母。题记号按元数区分一元G与二元G；严格固定签名时可分别记G₁、G₂，以下沿用原记法。',r'消去外蕴涵，得¬∀u(F(u)→G(u))∨∃vG(v,y)。量词否定为∃u¬(F(u)→G(u))∨∃vG(v,y)，再把¬(F→G)化为F∧¬G。',r'u不在右分支自由、v不在左分支自由，可依次外提，得∃u∃v((F(u)∧¬G(u))∨G(v,y))。全部量词在前、矩阵无量词，且原自由y仍自由，完成。'],[r'换名须同步改指导变元及其辖域内受约束出现。',r'不能为了统一字母而把原自由y也改成受约束出现。'])
put(12,[r'统一流程：先将互不相同辖域的约束变元换成新字母，保留全部自由出现；消→、↔，将否定推过量词，确认邻接分支无该变元自由出现才外提。按非空域约定使用这些等值式。',r'第（1）先成(∀uF(u))→∀vG(x,v)，x在后件自由。消箭头、量词否定得(∃u¬F(u))∨∀vG(x,v)，外提为∃u∀v(¬F(u)∨G(x,v))。',r'第（2）内∃y换u，成∀x(F(x,y)→∃uG(x,u,z))；消箭头成∀x(¬F(x,y)∨∃uG(x,u,z))，u不在前支自由，得∀x∃u(¬F(x,y)∨G(x,u,z))。原y、z保持自由。',r'第（3）设A=∀xF(x,y)，B=∃xG(x,y)，先把A↔B展开(A→B)∧(B→A)。第一支为∃u∃v(¬F(u,y)∨G(v,y))；第二支为∀s∀t(¬G(s,y)∨F(t,y))。不同支新变元互不自由出现，合取外提得 $$\exists u\exists v\forall s\forall t[(\neg F(u,y)\lor G(v,y))\land(\neg G(s,y)\lor F(t,y))].$$',r'第（4）约束x₁换u、H中约束x₂换v、存在x₃换w。A→(B→C)≡¬A∨¬B∨C，因此矩阵先成(∃u(F(u)∧¬G(u,x₂)))∨(∀v¬H(v))∨∃wL(x₂,w)。外提得 $$\exists u\forall v\exists w[(F(u)\land\neg G(u,x_2))\lor\neg H(v)\lor L(x_2,w)].$$x₂在G、L中始终自由。',r'第（5）前件∃x₁换u、末尾∃x₂换v，两个后件中的x₁及前件中的x₂自由。消两层蕴涵、量词否定，得(∀u¬F(u,x₂))∨¬F(x₁)∨∀v¬G(x₁,v)，外提为 $$\forall u\forall v(\neg F(u,x_2)\lor\neg F(x_1)\lor\neg G(x_1,v)).$$F按原题元数区分一元与二元，固定签名可另记F₁、F₂。'],[r'第（3）双条件须复制成两个方向，两个副本的约束变元还要分别换新名。',r'外提蕴涵前件的量词会反转；最安全是先消箭头再用量词否定。',r'原自由x、y或x₁、x₂不能被新量词捕获。'])
put(13,[r'域交通工具，C汽车、T火车、P飞机、R(x,y)为x比y快。第（1）∃x∃y(C(x)∧T(y)∧R(x,y))，两个存在见证同时满足类别与关系，已经前束。',r'第（2）先写∃x(T(x)∧∀y(C(y)→R(x,y)))。因T(x)无自由y，可外提∀y，再消矩阵箭头，得∃x∀y(T(x)∧(¬C(y)∨R(x,y)))。',r'第（3）否定全称“所有火车比所有汽车快”，量词与蕴涵否定给∃x∃y(T(x)∧C(y)∧¬R(x,y))。第（4）否定“有的飞机比有的汽车慢”，慢写R(y,x)，否定两个存在得∀x∀y(¬P(x)∨¬C(y)∨¬R(y,x))。',r'四式均是完整量词前缀加无量词矩阵，量词顺序表达指定见证是否可以依赖另一个对象。'],[r'飞机慢于汽车应写汽车快于飞机，R的参数次序须倒换。',r'全称量词外提后，类别条件仍要留在矩阵正确的合取或蕴涵位置。'])
put(14,[r'存在引入∃+要求项对被代换变元可自由代入，避免被其他量词捕获。例如从∀xR(x,c)错推∃x∀xR(x,x)，把常项c替成x后，出现落进内部∀x辖域被捕获。',r'反模型D={0,1},c=0,R={(0,0),(1,0)}：前提对两x均真；结论内∀xR(x,x)被x=1否定，外∃x为空约束，结论假。合法改用新z，结论∃z∀xR(x,z)，见证z=c，无捕获。',r'存在消去∃−只能用新临时见证，不能从∃xF(x)就推出某个原先已指定c的F(c)。取D={0,1},F={1},c=0，存在前提真而F(c)假。',r'合法用法是在临时F(d)假设下推到不含新d的目标，再解除见证；d不得预先出现在相关未解除前提、存在矩阵或最终结论中。否则推到的结论可能只对被特殊选中的d成立。'],[r'存在引入不是任意替换字母，先检查是否捕获。',r'存在消去新常项只是临时未知见证，不能偷换成已经命名的特定个体。'])
put(15,[r'第（1）由前提(∃xF(x))→∀y((F(y)∨G(y))→R(y))与∃xF(x)，假言推理得全称后件。对存在前提开子证明F(c)，c全新。全称消去给(F(c)∨G(c))→R(c)；由F(c)附加得F(c)∨G(c)，推出R(c)，存在引入∃xR(x)。目标不含c，解除存在子证明。',r'第（2）对∃xF(x)开新见证F(c)。全称消去得F(c)→(G(a)∧R(c))，推出G(a)∧R(c)，化简取R(c)；与F(c)合取得F(c)∧R(c)，存在引入∃x(F(x)∧R(x))，再解除c。题中已有a不能拿来替代新c。',r'第（3）¬∃xG(x)等值∀x¬G(x)。非空域取一个任意新个体c，全称消去得到F(c)∨G(c)和¬G(c)，析取三段论推出F(c)，存在引入∃xF(x)。这里未从不存在见证中擅取个体，使用的是非空域。',r'第（4）任取新c，三全称前提实例化为F(c)∨G(c)、¬G(c)∨¬R(c)、R(c)。由后两式析取三段论得¬G(c)，再与第一式得F(c)。c任意且不在未解除前提中自由，得∀xF(x)。'],[r'第（1）、（2）新见证必须在存在引入后的结论中消失。',r'第（4）要对任意c证明，不能只用某个存在见证就全称化。'])
put(16,[r'要证明不等值，只需同一个解释使真值不同。取D={0,1},F={0},G=∅。',r'∀xF(x)因F(1)=0而假，∀xG(x)也假，故第一式0→0=1。',r'第二式在x=0有F(0)=1、G(0)=0，所以F(0)→G(0)=0，外全称式假。这样同时满足第一真、第二假的要求，不能把前者当成逐点条件。'],[r'整体全称蕴涵会因∀F假而空真，即便某个点F真G假。',r'反模型必须用同一域和同一F、G解释比较。'])
put(17,[r'原证附加的是更强的闭式∀xH(x)。在此附加条件下确可逐点推G、¬F，进而得到∀x¬F(x)，但每一步仍依赖这条额外假设。',r'若合法解除该假设，实际得到(∀xH(x))→∀x¬F(x)，与目标∀x(H(x)→¬F(x))不是同一形式。前者在并非所有人H时前件假，不能据此覆盖那些确实H的个体。',r'错误不能简单说第⑨全称引入必然违法：附加前提∀xH(x)是闭式，并无自由x，故那一步本身可满足规则。实质是没有证明正确的局部条件命题，以及未解除就把依赖额外假设的结果当原前提结论。',r'修正应任取c，只暂设H(c)，推¬F(c)，解除后得到H(c)→¬F(c)，再对任意c全称化。这样每个H个体都被覆盖，无需假定全域H。'],[r'指出错误应追踪假设依赖，不能无根据地把闭式前提说成含自由x。',r'更强前提下的结论不自动成为原前提的结论。'])
put(18,[r'任取新个体参数c，开条件证明暂设H(c)。由∀x(H(x)→G(x))全称消去得H(c)→G(c)，与暂设假言推理得G(c)。',r'由∀x(F(x)→¬G(x))全称消去得F(c)→¬G(c)。再暂设F(c)，可推出¬G(c)，与已得G(c)矛盾，解除内假设得¬F(c)。这也可写拒取式加双重否定。',r'解除外假设H(c)，得H(c)→¬F(c)。此时不再有含c的局部未解除前提，c在原前提中全新且任意，故全称引入得∀x(H(x)→¬F(x))。'],[r'全称引入前要先解除H(c)，否则c仍受局部特殊假设限制。',r'由G(c)否定后件¬G(c)时需明确双重否定，或直接用反证。'])
put(19,[r'任取新c，暂设F(c)。由存在引入得到∃xF(x)，见证就是c。',r'将此存在式与原前提(∃xF(x))→∀xG(x)作假言推理，得到∀xG(x)，全称消去取同一c得G(c)。',r'解除F(c)，得F(c)→G(c)。c任意、原前提是闭式且无c，自由假设已解除，故全称引入∀x(F(x)→G(x))。这证明所需单向蕴涵，不宣称反向等价。'],[r'不能直接从原条件前提推出∀G，须先在子证明中建立∃F。',r'最后全称化针对任意c，不能只选一个特定满足F的人。'])
put(20,[r'第（1）暂设∀xF(x)。任取c，原全称前提给F(c)→G(c)，暂设给F(c)，假言推理得G(c)。c在未解除前提中无自由出现，可全称引入∀xG(x)，再解除∀xF(x)，得(∀xF(x))→∀xG(x)。',r'第（2）暂设¬∀xF(x)，用量词否定得∃x¬F(x)。开存在子证明¬F(c)，c全新；原前提实例化给F(c)∨G(c)，析取三段论得G(c)，再存在引入∃xG(x)。',r'第二问的目标∃xG(x)不含c，先解除存在见证子证明；再解除最外暂设¬∀xF(x)，得到所需蕴涵。两层解除次序与两种临时假设要分清。'],[r'第（2）存在的见证来自¬∀F，不可凭空选择已命名常项。',r'蕴涵证明要最终解除附加前提，不能只交付其下的结论。'])
put(21,[r'域取个体，W白色、C乌鸦、B北京鸭。前提¬∃x(W(x)∧C(x))、∀x(B(x)→W(x))；目标∀x(B(x)→¬C(x))。',r'第一前提量词否定与德摩根给∀x(¬W(x)∨¬C(x))，等值∀x(W(x)→¬C(x))。任取c，暂设B(c)，第二前提实例化并假言推理得W(c)。',r'第一前提实例化W(c)→¬C(c)，再得¬C(c)。解除B(c)为B(c)→¬C(c)，然后任意c全称化得目标。教材事实作为已给前提，证明只使用它们的逻辑关系。'],[r'“没有白乌鸦”不表示没有任何白色物体，只排除交集。',r'要证明所有北京鸭，需任意c而非只取一只鸭。'])
put(22,[r'第（1）域整数，E为偶、T为能被2整除。前提∀x(E(x)→T(x))及E(6)，结论T(6)。以项6作全称消去得E(6)→T(6)，再与E(6)假言推理得T(6)，不需存在量词规则。',r'第（2）域人，U大学生、D勤奋、w为王晓山。前提∀x(U(x)→D(x))、¬D(w)。全称消去得U(w)→D(w)，与¬D(w)用拒取式得¬U(w)。',r'第二问若改为D(w)就不能反推U(w)，那是肯定后件；本题给的是否定后件，规则方向合法。常项w在这一具体个体论证中无须全称化。'],[r'具体常项6与w可直接全称实例化，不必新增存在见证。',r'否定后件能否定前件，肯定后件一般不能肯定前件。'])
put(23,[r'第（1）Q有理、R实数、Z整数，前提∀x(Q(x)→R(x))、∃x(Q(x)∧Z(x))。新见证子证明Q(c)∧Z(c)先化简为Q(c)、Z(c)，再从Q(c)→R(c)得R(c)，合取得R(c)∧Z(c)，存在引入∃x(R(x)∧Z(x))，结论不含c，解除见证。',r'第（2）另S无理、I虚数，前提∀x(Q→R)、∀x(S→R)、∀x(I→¬R)。任取c暂设I(c)，第三前提得¬R(c)。',r'前两前提实例化Q(c)→R(c)、S(c)→R(c)，分别拒取得¬Q(c)、¬S(c)，合取得¬Q(c)∧¬S(c)。解除I(c)后全称化，得到∀x(I(x)→(¬Q(x)∧¬S(x)))。',r'第二问使用虚数这个谓词所给的不为实数前提，不引入“复数全都非实”的额外断言。所有类别约束都来自原前提。'],[r'第（1）需保留同一见证的Z(c)，不能转成与另一个人有关的独立存在事实。',r'“既不是Q也不是S”用¬Q∧¬S，不是¬Q∨¬S。'])
put(24,[r'域人，W步行、B骑车、C乘汽车，前提∀x(W(x)→¬B(x))、∀x(B(x)∨C(x))、∃x¬C(x)，目标∃x¬W(x)。',r'从存在前提开新见证¬C(c)。第二前提实例化B(c)∨C(c)，排除C(c)后得B(c)。第一前提实例化W(c)→¬B(c)。',r'若暂设W(c)，将得¬B(c)，与B(c)矛盾，故¬W(c)。存在引入∃x¬W(x)，此结论不含新c，消去临时见证，完成。',r'这里原析取为相容析取也可，排除C已经迫使B，不必额外假设每个人恰好喜欢其中一种。'],[r'见证取自不喜欢汽车者，不能改取任意人都不喜欢汽车。',r'步行推出不骑车，已知骑车时用拒取或反证才能得不步行。'])
put(25,[r'域人，S科学工作者、H刻苦钻研、C聪明、R成功，w王大海。前提∀x(S(x)→H(x))、∀x((H(x)∧C(x))→R(x))、S(w)∧C(w)，目标R(w)。',r'合取消去第三前提得S(w)、C(w)。第一前提全称消去S(w)→H(w)，与S(w)假言推理得H(w)。',r'将H(w)、C(w)合取成H(w)∧C(w)；第二前提全称消去得(H(w)∧C(w))→R(w)，再假言推理得R(w)。两项条件都齐备才触发成功规则。'],[r'第二规则前件是刻苦且聪明，仅有一项不够。',r'所有谓词都指同一个w，不能把不同人的条件拼到一起。'])

example('086-2572',[r'第（1）原x在左受∀x约束、在右自由；原y在左自由、在右受∃y约束。只将左绑定x及其受辖出现换t，右绑定y及其受辖出现换w，得(∀tF(t,y,z))→∃wG(x,w,z)。',r'第（2）原x都受同一个∀x约束，z自由；仅y同时有自由、约束出现。把内存在y换t，得∀x(F(x,y)→∃tG(x,t,z))。',r'两式中新t、w都只约束出现，原自由变项仍保留。换名是绑定结构的重标记，不是全局把某个字母一律替换，因此等值且满足要求。'],[r'不能把F中的自由y随内∃y一起改名。',r'所选新字母须未在相关位置使用，避免引入捕获。'])
example('086-5407',[r'统一取自然数域，A为奇数、B为偶数。每个自然数二者恰居一类，且0为偶、1为奇，两类均非空。',r'第（1）∀x(A∨B)真；但0否定∀A，1否定∀B，右式(∀A)∨(∀B)=0∨0假，故不等值。全称并不这样分配到同变元析取。',r'第（2）没有数同时奇偶，∃x(A∧B)假；但∃A有见证1、∃B有见证0，两存在合取真，故不等值。存在合取的同一见证要求不能拆散。'],[r'要用同一个域、同一谓词解释比较两侧。',r'∀对合取、∃对析取可以分配，换成这里的交叉形式一般不行。'])
example('086-8582',[r'第（1）有限域全称直接成三个实例的合取：(F(a)→G(a))∧(F(b)→G(b))∧(F(c)→G(c))。每个实例都要用同一个域元素替换F、G的x。',r'第（2）先展开内存在Q=G(a)∨G(b)∨G(c)，再外全称得(F(a)∨Q)∧(F(b)∨Q)∧(F(c)∨Q)。两次分配得(F(a)∧F(b)∧F(c))∨Q。也可先用无自由x条件收缩辖域，结果相同。',r'第（3）∃x∀yF(x,y)需至少一个全真行，所以为(F(a,a)∧F(a,b)∧F(a,c))∨(F(b,a)∧F(b,b)∧F(b,c))∨(F(c,a)∧F(c,b)∧F(c,c))。先对y合取、再对x析取，顺序不可互换。'],[r'二元实例的第一个坐标固定x行，第二个坐标随y列。',r'不能把第（3）写成每行有真点，那表达的是∀x∃y。'])
example('087-3788',[r'第（1）a=2，展开∀成两项：(F(2)∧G(2,2))∧(F(3)∧G(3,2))=(0∧1)∧(1∧1)=0，假。',r'第（2）f交换2、3，展开存在：(F(3)∧G(2,3))∨(F(2)∧G(3,2))=(1∧1)∨(0∧1)=1，见证x=2，真。',r'第（3）L的表为单位表，每行都有对角1，故∀x∃y展开为(1∨0)∧(0∨1)=1，真。第（4）每列都含0，无全真列，∃y∀x展开为(1∧0)∨(0∧1)=0，假。'],[r'G(x,f(x))要先算函数值，再查二元表。',r'第（4）固定y检查整列，与固定x检查整行不同。'])
example('088-1379',[r'第（1）¬∃x(M∧F)≡∀x¬(M∧F)（量词否定）≡∀x(¬M∨¬F)（德摩根）≡∀x(M→¬F)（蕴涵等值），M、F此处简记同x的谓词。',r'第（2）¬∀x(M→F)≡∃x¬(¬M∨F)（量词否定、消箭头）≡∃x(M∧¬F)（德摩根、双重否定）。',r'第（3）两次量词否定给∃x∃y¬((F(x)∧G(y))→H(x,y))，用¬(A→B)≡A∧¬B，恰为∃x∃y(F(x)∧G(y)∧¬H(x,y))。',r'第（4）两次量词否定给∀x∀y¬(F(x)∧G(y)∧L(x,y))，德摩根组合成∀x∀y(¬(F(x)∧G(y))∨¬L(x,y))，还原蕴涵即右式。每步保留原变元的绑定，不发生换名或捕获。'],[r'否定通过每一层量词都要反转一次。',r'否定蕴涵给前件真且后件假，不是另一个箭头。'])
example('089-2595',[r'第（1）先将右约束x换y，且¬∃yG(y)≡∀y¬G(y)，得(∀xF(x))∧∀y¬G(y)。x不在右支自由、y不在左支自由，外提为∀x∀y(F(x)∧¬G(y))。',r'由于∀对合取分配，还可共享同一量化变量写更短∀x(F(x)∧¬G(x))：两者都要求每个元素满足F且每个元素不满足G。',r'第（2）同样换名并推否定，得(∀xF(x))∨∀y¬G(y)。依外提条件得∀x∀y(F(x)∨¬G(y))。这里不能再合并为∀x(F(x)∨¬G(x))，该错误版本只要求逐点析取，弱于原式。'],[r'合取中的两个全称可共享变量，析取一般不行。',r'相同指导变元先换名，可以明确两个量词的独立辖域。'])
example('089-8087',[r'第（1）先换左约束x为y，得(∃yF(y))∧∀xG(x)。y不在右支自由、x不在左支自由，先提∃y再提∀x，成∃y∀x(F(y)∧G(x))。',r'第（2）换名成(∀yF(y))→∃xG(x)，消箭头为¬∀yF(y)∨∃xG(x)，量词否定为(∃y¬F(y))∨∃xG(x)，外提成∃y∃x(¬F(y)∨G(x))，也可把矩阵写F(y)→G(x)。',r'第（3）换名成(∃yF(y))→∀xG(x)，消箭头、量词否定得(∀y¬F(y))∨∀xG(x)，外提为∀y∀x(¬F(y)∨G(x))。',r'后两问蕴涵前件量词外移时反转，原因正是消箭头带来的前件否定；后件量词不反转。各前束矩阵均无量词。'],[r'全称在箭头前件移出变存在，存在变全称。',r'不能把前件外提规则误用于后件，后件量词保持类型。'])
example('090-3826',[r'第（1）前件约束x换t、后件约束y换w，成(∀tF(t,y))→∃wG(x,w)，原x、y自由保留。消箭头成∃t¬F(t,y)∨∃wG(x,w)，外提为∃t∃w(¬F(t,y)∨G(x,w))。',r'第（2）先改绑定x₁为x₄、绑定x₂为x₅，得到((∀x₄F(x₄,x₂))→∃x₅G(x₅))→∀x₁H(x₁,x₂,x₃)。其中x₂、x₃自由，后件x₁仍约束，互无捕获。',r'内层蕴涵先外提为∃x₄∃x₅(F(x₄,x₂)→G(x₅))。它整个成为外蕴涵前件，两存在因前件否定依次反转全称，后件∀x₁保持全称。',r'所以可取 $$\forall x_4\forall x_5\forall x_1((F(x_4,x_2)\to G(x_5))\to H(x_1,x_2,x_3)).$$相邻全称x₄、x₅可互换，与原答案顺序等值；矩阵中的两个箭头允许保留，因为已无量词。'],[r'内层前件的全称被反转一次，随后整个内蕴涵又被否定，需逐层追踪。',r'前束范式矩阵允许箭头，不要求额外化成命题合取范式。'])
example('093-8613',[r'域实数，F自然数、G整数，前提∀x(F(x)→G(x))及∃xF(x)，目标∃xG(x)。域比自然数广，不能把“所有个体是自然数”当隐含前提。',r'对存在前提开临时见证F(c)，c为全新符号。全称前提实例化F(c)→G(c)，与F(c)假言推理得到G(c)。',r'由G(c)存在引入∃xG(x)。目标不含c，且原前提中未使用c，消去存在见证子证明。每一步只传递同一个见证所属类别，不需要具体说c是哪一个自然数。'],[r'不能从∃F推出任意指定实数都F。',r'结论应消去临时c，不能把G(c)作为脱离子证明的最终结论。'])
example('094-3284',[r'从∃x(F(x)∧H(x))开全新c的子证明，暂设F(c)∧H(c)，合取消去得到两项F(c)、H(c)。',r'∀x(F(x)→G(x))全称消去得到F(c)→G(c)，假言推理给G(c)。与仍保留的H(c)合取成G(c)∧H(c)。',r'存在引入∃x(G(x)∧H(x))，该目标不含c，解除临时见证。H之所以能保留，是它与F来自同一见证的合取，不是另外某个满足H的个体。'],[r'不要把原存在合取拆成两个独立见证后再随意合回。',r'要保留H(c)直到最后合取，不应在推G(c)时丢掉。'])
example('094-6406',[r'域实数，F无理、G有理、H可写分数。前提¬∃x(F(x)∧H(x))、∀x(G(x)→H(x))；目标∀x(G(x)→¬F(x))。',r'第一前提量词否定、德摩根成∀x(¬F(x)∨¬H(x))，等值∀x(H(x)→¬F(x))，把H作前件更便于与第二前提衔接。',r'任取新c暂设G(c)，第二前提得H(c)，第一前提得H(c)→¬F(c)，再推出¬F(c)。解除暂设成G(c)→¬F(c)，c任意且无未解除局部依赖，全称引入即结论。'],[r'“不存在无理且可写分数”排除交集，不能误成两类都不存在。',r'全称引入前先解除有理数的局部假设。'])

if __name__=='__main__':author.main()
